// The list Telegram suggests when someone types / in a chat with the bot.
// It is what BotFather's /setcommands sets, kept here so it changes along
// with the commands. Everyone gets the first list, a group the commands that
// work there, and each admin the longer list in their own chat. Each list is
// set twice: in English for everyone, and in Finnish for whoever has their
// Telegram in Finnish (language_code fi), as the bot's answers are. Runs
// every morning, so a new admin gets theirs the next day at the latest; Run
// now does it straight away.
// Jira: DM42-33, DM42-36
const WORDS = {
  en: {
    login: 'Open the dashboard: a link that works once',
    password: 'Choose a password, to log in without Telegram',
    check: 'Check all sources now',
    schedule: 'See or set when I check the sources',
    reschedule: 'Change when I check the sources',
    help: 'What I can do',
    adduser: 'An account for the dashboard: /adduser email Name',
    people: 'Who can use me and the dashboard',
    remove: 'Take someone off the list: /remove Name',
    alerts: 'Where I report problems',
  },
  fi: {
    login: 'Avaa dashboard: linkki, joka toimii kerran',
    password: 'Valitse salasana, niin voit kirjautua ilman Telegramia',
    check: 'Tarkista kaikki lähteet nyt',
    schedule: 'Katso tai aseta, milloin tarkistan lähteet',
    reschedule: 'Muuta lähteiden tarkistusaikoja',
    help: 'Mitä osaan',
    adduser: 'Tili dashboardiin: /adduser sähköposti Nimi',
    people: 'Kuka voi käyttää minua ja dashboardia',
    remove: 'Poista henkilö listalta: /remove Nimi',
    alerts: 'Minne ilmoitan ongelmista',
  },
};
// /alerts in a group makes it the place for problem reports.
const IN_A_GROUP = {
  en: { alerts: 'Report problems in this group (admins)' },
  fi: { alerts: 'Ilmoita ongelmista tässä ryhmässä (ylläpitäjät)' },
};
const EVERYONE = ['login', 'password', 'check', 'schedule', 'reschedule', 'help'];
const ADMINS = [...EVERYONE, 'adduser', 'people', 'remove', 'alerts'];
const GROUPS = ['check', 'schedule', 'reschedule', 'alerts', 'help'];
const menu = (names, lang, group = false) => names.map((command) => ({
  command, description: (group && IN_A_GROUP[lang][command]) || WORDS[lang][command],
}));
// Finnish is set with language_code fi; English is the list for everyone else.
const LANGS = [['en', {}], ['fi', { language_code: 'fi' }]];

const telegram = (method, body) => this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`,
  body,
  json: true,
});

for (const [lang, code] of LANGS) {
  await telegram('setMyCommands', { commands: menu(EVERYONE, lang), ...code });
  await telegram('setMyCommands', { commands: menu(GROUPS, lang, true), scope: { type: 'all_group_chats' }, ...code });
}
let admins = 0;
let others = 0;
let skipped = 0;
for (const { json: person } of $input.all()) {
  if (!person.telegram_user_id) continue;
  const scope = { type: 'chat', chat_id: Number(person.telegram_user_id) };
  try {
    for (const [lang, code] of LANGS) {
      if (person.admin) await telegram('setMyCommands', { commands: menu(ADMINS, lang), scope, ...code });
      else await telegram('deleteMyCommands', { scope, ...code });
    }
    if (person.admin) admins++;
    else others++;
  } catch (e) {
    // Someone who has blocked the bot since. Their chat has no menu to set.
    skipped++;
  }
}
return [{ json: { everyone: EVERYONE.length, admin_chats: admins, other_chats: others, skipped } }];
